mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  p.yz = rot(time * 0.2) * p.yz;
  float shell = abs(length(p) - 1.25) - 0.08;
  float holes = dot(sin(p * 5.0), cos(p.zxy * 5.0)) - 0.25;
  float star = length(p) - (0.45 + 0.1 * sin(time * 4.0) * bass);
  return min(max(shell, holes), star);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0, glow = 0.0;
  for (int i = 0; i < 48; i++) {
    vec3 pos = ro + rd * t;
    float d = map(pos);
    glow += 0.012 / (0.04 + abs(d) * abs(d) * 14.0);
    if (d < 0.003 || t > 7.0) break;
    t += d * 0.8;
  }
  vec3 col = glow * vec3(0.1, 0.6, 1.2) * (0.8 + 0.4 * bass);
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
